#include <stdio.h>
// 异步全互锁：主发 REQ -> 等 ACK -> 撤 REQ -> 等 ACK 撤；双向互等，绝不失步
int main() {
    int n = 3;
    printf("异步全互锁握手: 传送 %d 字节\n", n);
    printf("step   事件\n");
    int s = 0;
    for (int b = 0; b < n; b++) {
        printf("  %d    主: 断言 REQ (放上第%d字节数据)\n", s++, b);
        printf("  %d    从: 收到 REQ, 断言 ACK\n", s++);
        printf("  %d    主: 见 ACK, 撤 REQ\n", s++);
        printf("  %d    从: 见 REQ 撤, 撤 ACK (第%d字节完成)\n", s++, b);
    }
    printf("共 %d 步 (每字节 4 步全互锁)\n", s);
    return 0;
}
